}

.image-carousel {
    position: relative;
    aspect-ratio: 3 / 2;
    min-height: 150px;
}

.carousel-track {
    display: flex;
    height: 100%;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scroll-behavior: smooth;
    -ms-overflow-style: none;
    touch-action: pan-x pan-y pinch-zoom;
    overscroll-behavior-x: contain;
    -webkit-overflow-scrolling: touch;
}

.carousel-track::-webkit-scrollbar {
    height: 0;
    display: none;
}

.carousel-track {
    scrollbar-width: none;
}

.carousel-track img {
    flex: 0 0 100%;
    width: 100%;
    min-width: 100%;
    max-width: 100%;
    height: 100%;
    object-fit: cover;
    scroll-snap-align: start;
    scroll-snap-stop: always;
    cursor: pointer;
    -webkit-user-drag: none;
    user-select: none;
    touch-action: pan-x pan-y pinch-zoom;
}

img[data-sitewide-image-swipe-bound="1"] {
    -webkit-user-drag: none;
    user-select: none;
    transition: opacity 0.18s ease, transform 0.18s ease;
}

img[data-sitewide-image-swipe-bound="1"].is-sitewide-image-dragging {
    cursor: grabbing;
}

img[data-sitewide-image-swipe-bound="1"].is-sitewide-swipe-changing {
    opacity: 0.82;
    transform: scale(0.995);
}

.vehicle-featured-top .vehicle-featured-static .carousel-track img {
    cursor: grab;
}

.vehicle-featured-top .vehicle-featured-static .carousel-track img:active {
    cursor: grabbing;
}

.carousel-btn {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 32px;
    height: 32px;
    border-radius: 999px;
    border: 1px solid rgba(148, 163, 184, 0.4);
    background: rgba(15, 23, 42, 0.75);
    color: #f8fafc;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 2;
}

.carousel-btn[hidden] {
    display: none !important;
}

.carousel-btn.prev { left: 0.5rem; }
.carousel-btn.next { right: 0.5rem; }

.carousel-btn:focus-visible {
    outline: 2px solid rgba(250, 204, 21, 0.7);
    outline-offset: 2px;
}

.image-carousel.has-mobile-carousel-dots .mobile-carousel-dots,
.standalone-photo-dots {
    position: absolute;
    left: 50%;
    bottom: 0.6rem;
    transform: translateX(-50%);
    z-index: 12;
    display: flex;
    align-items: center;
    width: max-content;
    max-width: calc(100% - 16px);
    gap: 3px;
    padding: 3px 5px;
    border: 1px solid rgba(255, 255, 255, 0.25);
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.68);
    overflow-x: auto;
    scrollbar-width: none;
    touch-action: pan-x;
    overscroll-behavior-x: contain;
}

.photo-dots-host { position: relative; }
.standalone-photo-dots {
    bottom: auto;
    transform: translate(-50%, -100%);
}
.standalone-photo-dots[hidden] { display: none; }
.standalone-photo-dots::-webkit-scrollbar,
.mobile-carousel-dots::-webkit-scrollbar { display: none; }
.standalone-photo-dot {
    flex: 0 0 24px;
    width: 24px;
    height: 24px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: transparent;
    display: grid;
    place-items: center;
    cursor: pointer;
}
.standalone-photo-dot::after {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.55);
}
.standalone-photo-dot.active::after {
    background: #ffffff;
    box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.28);
}
.standalone-photo-dot:focus-visible {
    outline: 2px solid #facc15;
    outline-offset: -2px;
}

.mobile-carousel-dot {
    flex-shrink: 0;
    width: 7px;
    height: 7px;
    border: 0;
    border-radius: 999px;
    padding: 0;
    background: rgba(255, 255, 255, 0.62);
