/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --app-max-width: 1320px;
    --app-gutter: clamp(1rem, 2.4vw, 2rem);
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background: #f5f9ff;
    min-height: 100vh;
    overflow-x: hidden;
}

/* Home Screen */
#home-screen {
    min-height: 100vh;
    padding: 5rem min(6vw, 4rem) 4rem;
    background: linear-gradient(180deg, #0f4af0 0%, #0f4af0 55%, #f8fafc 55%);
    display: flex;
    align-items: center;
    justify-content: center;
}

.home-wrapper {
    width: 100%;
    max-width: 1100px;
    display: flex;
    flex-direction: column;
    gap: 3rem;
    color: #fff;
}

.home-hero {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    max-width: 520px;
}

.home-logo {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 2.75rem;
    font-weight: 800;
}

.home-logo i {
    font-size: 2.75rem;
}

.home-lead {
    font-size: 1.15rem;
    line-height: 1.7;
    opacity: 0.95;
}

.home-actions {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.home-actions .btn-secondary {
    border-color: rgba(255,255,255,0.75);
    color: #0f4af0;
    background: white;
}

.home-feature-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 1.25rem;
}

.home-feature {
    background: #fff;
    border-radius: 18px;
    padding: 1.6rem;
    box-shadow: 0 22px 40px -24px rgba(15, 74, 240, 0.45);
    color: #0b1f4d;
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.home-feature i {
    font-size: 1.8rem;
    color: #0f4af0;
}

.home-feature h3 {
    font-size: 1.1rem;
    font-weight: 700;
}

.home-feature p {
    font-size: 0.95rem;
    color: #3b4a70;
    line-height: 1.5;
}

@media (max-width: 768px) {
    #home-screen {
        padding: 4rem 1.5rem 3rem;
        background: linear-gradient(180deg, #0f4af0 0%, #0f4af0 62%, #f8fafc 62%);
    }

    .home-logo {
        font-size: 2.3rem;
    }

    .home-logo i {
        font-size: 2.3rem;
    }

    .home-lead {
        font-size: 1.05rem;
    }
}

@media (max-width: 540px) {
    .home-actions {
        flex-direction: column;
        align-items: stretch;
    }

    .home-feature-grid {
        grid-template-columns: 1fr;
    }
}

/* Loading Screen */
.loading-screen {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%);
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    z-index: 1000;
    color: white;
}

.loading-logo {
    width: clamp(92px, 18vw, 150px);
    height: auto;
    margin-bottom: 1.35rem;
    filter: drop-shadow(0 10px 26px rgba(0, 0, 0, 0.24));
    animation: logo-sway 2.4s ease-in-out infinite;
}

@keyframes logo-sway {
    0% { transform: translateX(-10px) translateY(0) rotate(-2deg); }
    50% { transform: translateX(10px) translateY(-8px) rotate(2deg); }
    100% { transform: translateX(-10px) translateY(0) rotate(-2deg); }
}

.loading-screen h1,
.loading-screen .loading-brand {
    font-size: 2.5rem;
    margin-bottom: 1rem;
    font-weight: 700;
}

.loading-screen p {
    font-size: 1.2rem;
    opacity: 0.8;
}

/* Screen Management */
.screen {
    width: 100%;
    min-height: 100vh;
    position: absolute;
    top: 0;
    left: 0;
}

.hidden {
    display: none !important;
}

.coming-soon-gate {
    position: fixed;
    inset: 0;
    z-index: 900;
    display: grid;
    place-items: center;
    min-height: 100vh;
    padding: clamp(1rem, 3vw, 2.5rem);
    color: #f8fafc;
    background:
        radial-gradient(circle at 18% 28%, rgba(30, 64, 175, 0.22) 0 1px, transparent 2px),
        radial-gradient(circle at 72% 18%, rgba(96, 165, 250, 0.2) 0 1px, transparent 2px),
        radial-gradient(circle at 84% 72%, rgba(255, 255, 255, 0.32) 0 1px, transparent 2px),
        radial-gradient(circle at 34% 78%, rgba(30, 58, 138, 0.24) 0 1px, transparent 2px),
        linear-gradient(125deg, rgba(2, 6, 23, 0.98) 0%, rgba(5, 20, 58, 0.98) 42%, rgba(6, 45, 66, 0.96) 100%);
    overflow: hidden;
}

.coming-soon-gate::before,
.coming-soon-gate::after {
    content: "";
    position: absolute;
    inset: -20%;
    pointer-events: none;
}

