    overflow: hidden;
    isolation: isolate;
    backdrop-filter: blur(14px) saturate(1.15);
    z-index: 250;
}

.bottom-nav::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background:
        radial-gradient(circle at 18% 30%, rgba(255, 255, 255, 0.46) 0 1px, transparent 2px) 0 0 / 170px 170px,
        radial-gradient(circle at 72% 40%, rgba(255, 255, 255, 0.32) 0 1px, transparent 2px) 0 0 / 220px 220px,
        radial-gradient(circle at 40% 80%, rgba(255, 255, 255, 0.22) 0 1px, transparent 2px) 0 0 / 260px 260px;
    pointer-events: none;
    opacity: 0.55;
    z-index: 0;
}

.bottom-nav::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.10) 0%, transparent 35%, rgba(15, 23, 42, 0.34) 100%),
        radial-gradient(520px circle at 50% 0%, rgba(255, 255, 255, 0.07), transparent 62%);
    pointer-events: none;
    z-index: 0;
}

.nav-btn-group {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    min-width: 0;
    position: relative;
    z-index: 1;
}

.nav-btn {
    background: none;
    border: none;
    display: flex;
    flex-direction: column;
    align-items: center;
    color: rgba(226, 232, 240, 0.72);
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.3s ease;
    padding: 0.5rem;
    border-radius: 14px;
    position: relative;
}

.nav-btn.active {
    color: rgba(250, 204, 21, 0.96);
}

.nav-btn i {
    font-size: 1.5rem;
    margin-bottom: 0.25rem;
}

.nav-btn:hover {
    background: rgba(248, 250, 252, 0.06);
}

.nav-btn.active::after {
    content: "";
    position: absolute;
    bottom: 0.15rem;
    left: 50%;
    transform: translateX(-50%);
    width: 22px;
    height: 3px;
    border-radius: 999px;
    background: linear-gradient(90deg, rgba(250, 204, 21, 0.96), rgba(14, 165, 233, 0.65));
    box-shadow: 0 14px 30px rgba(250, 204, 21, 0.18);
}

