/* Vehicle modal */
.vehicle-modal {
    width: min(860px, calc(100% - 1.5rem));
    max-width: 860px;
    padding: 0;
    overflow-x: hidden;
    overflow-y: auto;
    border-radius: 18px;
}

.vehicle-modal-media {
    position: relative;
    background: rgba(2, 6, 23, 0.92);
    height: 420px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.vehicle-modal-photo {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
    isolation: isolate;
}

.vehicle-modal-photo::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: var(--gallery-backdrop-image, none);
    background-size: cover;
    background-position: center;
    transform: scale(1.08);
    filter: blur(26px) saturate(1.08);
    opacity: 0.72;
    z-index: 0;
}

.vehicle-modal-photo::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(2, 6, 23, 0.06) 0%, rgba(2, 6, 23, 0.62) 100%);
    pointer-events: none;
    z-index: 2;
}

#vehicle-modal-image {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    object-fit: contain;
    object-position: center center;
    padding: 0.35rem;
    filter: drop-shadow(0 18px 38px rgba(2, 6, 23, 0.28));
    display: block;
	cursor: zoom-in;
}

#vehicle-modal-image:focus-visible {
	outline: 3px solid rgba(56, 189, 248, 0.95);
	outline-offset: -5px;
}

.vehicle-media-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 40px;
    height: 40px;
    border-radius: 999px;
    border: 1px solid rgba(226, 232, 240, 0.22);
    background: rgba(2, 6, 23, 0.55);
    color: rgba(248, 250, 252, 0.98);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

#vehicle-media-prev { left: 0.85rem; }
#vehicle-media-next { right: 0.85rem; }

.vehicle-media-counter {
    position: absolute;
    bottom: 4.7rem;
    right: 0.85rem;
    padding: 0.3rem 0.6rem;
    border-radius: 999px;
    background: rgba(2, 6, 23, 0.55);
    border: 1px solid rgba(226, 232, 240, 0.16);
    color: rgba(248, 250, 252, 0.92);
    font-weight: 800;
    font-size: 0.85rem;
}

.vehicle-media-thumbs {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    gap: 0.45rem;
    padding: 0.55rem 0.75rem;
    overflow-x: auto;
    overflow-y: hidden;
    background: linear-gradient(180deg, rgba(2, 6, 23, 0) 0%, rgba(2, 6, 23, 0.72) 40%, rgba(2, 6, 23, 0.86) 100%);
    scrollbar-width: none;
}
.vehicle-media-thumbs::-webkit-scrollbar { display: none; }

.vehicle-media-thumb {
    flex: 0 0 auto;
    width: 54px;
    height: 40px;
    border-radius: 10px;
    border: 1px solid rgba(226, 232, 240, 0.18);
    background: rgba(15, 23, 42, 0.55);
    overflow: hidden;
    cursor: pointer;
    padding: 0;
}
.vehicle-media-thumb img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    filter: saturate(1.05) contrast(1.02);
}
.vehicle-media-thumb.active {
    border-color: rgba(56, 189, 248, 0.7);
    box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.25);
}

.vehicle-modal-body {
    padding: 1.1rem 1.15rem 1.2rem;
    background: rgba(255, 255, 255, 0.96);
}

.vehicle-modal-layout {
    display: grid;
