    gap: 1.25rem;
    align-items: start;
}

.vehicle-modal-body.is-standard-layout .vehicle-modal-layout {
    grid-template-columns: minmax(0, 1fr);
}

.vehicle-modal-main {
    display: grid;
    gap: 1rem;
