}

.vehicle-modal-reviews-head h4 {
    margin: 0.2rem 0 0;
    color: #0f172a;
}

.vehicle-modal-section-head h4 {
    margin: 0.2rem 0 0;
    color: #0f172a;
}

.vehicle-modal-review-list {
