@media (max-width: 980px) {
    .vehicle-modal-layout {
        grid-template-columns: minmax(0, 1fr);
    }

    .vehicle-modal-sidebar {
        position: static;
    }

    .vehicle-modal-specs.is-tight {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@media (max-width: 900px) {
    .vehicle-modal-specs.is-tight {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 640px) {
    .vehicle-modal-media { height: 320px; }
    .vehicle-media-counter { bottom: 4.5rem; }
    .vehicle-modal-actions { justify-content: stretch; flex-direction: column; }
    .vehicle-modal-specs.is-tight { grid-template-columns: 1fr; }
    .vehicle-modal-overview { gap: 0.58rem; }
    .vehicle-modal-head { gap: 0.7rem; }
    .vehicle-modal-head h3 { font-size: clamp(1.28rem, 5.2vw, 1.7rem); }
    .vehicle-modal-price { font-size: clamp(1.4rem, 5.4vw, 1.95rem); }
    .vehicle-modal-status { margin-top: 0; gap: 0.4rem; }
    .vehicle-status-chip { font-size: 0.75rem; }
    .vehicle-modal-trust { font-size: 0.9rem; }
    .vehicle-modal-booking-grid { grid-template-columns: 1fr; }
    .vehicle-modal-overview,
    .vehicle-modal-details-section,
    .vehicle-modal-booking,
    .vehicle-modal-reviews,
    .vehicle-modal-group {
        padding: 0.95rem;
        border-radius: 18px;
    }
    .vehicle-spec-row.is-wide {
        grid-column: auto;
    }
    .seller-profile-rental-summary { grid-template-columns: 1fr; }
    .seller-profile-rental-media { height: 220px; }
}

/* Real estate modal (luxury profile card) */
#realestate-modal {
    align-items: stretch;
    justify-content: center;
    padding: 0 !important;
    background: #ffffff;
}

#realestate-modal .modal-content.realestate-modal,
.realestate-modal {
    width: 100% !important;
    min-width: 100% !important;
    max-width: none !important;
    min-height: 100dvh !important;
    height: 100dvh !important;
    max-height: none !important;
    padding: 0;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    background: #ffffff;
    color: #0b1020;
    border-radius: 0 !important;
    border: none !important;
    box-shadow: none !important;
    margin: 0 !important;
}

#realestate-modal .modal-close-btn {
    background: rgba(248, 250, 252, 0.92);
    color: rgba(15, 23, 42, 0.95);
    border: 1px solid rgba(148, 163, 184, 0.35);
    box-shadow: 0 12px 30px rgba(2, 6, 23, 0.18);
}

#realestate-modal .modal-close-btn:hover {
    background: rgba(241, 245, 249, 0.98);
}

.realestate-modal-media {
    position: relative;
    height: min(56dvh, 560px);
    min-height: 320px;
    max-height: min(56dvh, 560px);
    background: #050814;
    display: flex;
    align-items: center;
    justify-content: center;
}

.realestate-modal-stage {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
}

.realestate-modal-stage::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: var(--realestate-stage-image, none);
    background-size: cover;
    background-position: center;
    transform: scale(1.08);
    filter: blur(26px) saturate(1.08);
    opacity: 0.72;
}

.realestate-modal-stage::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(180deg, rgba(2, 6, 23, 0.04) 0%, rgba(2, 6, 23, 0.72) 100%);
}

#realestate-modal-image,
#realestate-modal-video {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    display: block;
}

#realestate-modal-image {
    object-fit: contain;
    object-position: center center;
    padding: 0.3rem;
    filter: drop-shadow(0 18px 38px rgba(2, 6, 23, 0.28));
}

#realestate-modal-video {
    object-fit: cover;
    background: #050814;
}

.realestate-media-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 46px;
    height: 46px;
    border-radius: 999px;
    border: 1px solid rgba(37, 99, 235, 0.28);
    background: rgba(2, 6, 23, 0.62);
    color: rgba(248, 250, 252, 0.98);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 3;
    box-shadow: 0 14px 30px rgba(2, 6, 23, 0.22);
}

#realestate-media-prev { left: 1.4rem; }
#realestate-media-next { right: 1.4rem; }

.realestate-media-counter {
    position: absolute;
    bottom: 5.45rem;
    right: 1.35rem;
    padding: 0.42rem 0.72rem;
    border-radius: 999px;
    background: rgba(2, 6, 23, 0.62);
    border: 1px solid rgba(226, 232, 240, 0.16);
    color: rgba(248, 250, 252, 0.92);
    font-weight: 800;
    font-size: 0.85rem;
    z-index: 4;
    box-shadow: 0 14px 30px rgba(2, 6, 23, 0.2);
}

.realestate-featured-pill {
    position: absolute;
    left: 0.95rem;
    bottom: 0.95rem;
    background: linear-gradient(135deg, #60a5fa, #2563eb);
    color: #0b1020;
    padding: 0.35rem 0.75rem;
    border-radius: 999px;
    font-weight: 900;
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    box-shadow: 0 10px 25px rgba(37, 99, 235, 0.28);
    z-index: 4;
}

.realestate-media-thumbs {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    gap: 0.55rem;
    padding: 0.75rem 1rem 0.9rem;
    overflow-x: auto;
    overflow-y: hidden;
    background: linear-gradient(180deg, rgba(2, 6, 23, 0) 0%, rgba(2, 6, 23, 0.72) 40%, rgba(2, 6, 23, 0.86) 100%);
    scrollbar-width: none;
    z-index: 4;
}
.realestate-media-thumbs::-webkit-scrollbar { display: none; }

.realestate-media-thumb {
    flex: 0 0 auto;
    width: 72px;
    height: 54px;
    border-radius: 12px;
    border: 1px solid rgba(37, 99, 235, 0.18);
    background: rgba(15, 23, 42, 0.55);
