}

.realestate-availability-calendar-day.is-selected-pending {
    background: rgba(29, 78, 216, 0.2);
    border-color: rgba(29, 78, 216, 0.4);
    color: rgba(15, 23, 42, 0.96);
    font-weight: 800;
}

.realestate-availability-calendar-day.is-start,
.realestate-availability-calendar-day.is-end {
    background: linear-gradient(135deg, rgba(37, 99, 235, 0.95), rgba(14, 165, 233, 0.9));
    color: #ffffff;
    font-weight: 800;
    border-color: rgba(37, 99, 235, 0.9);
}

.realestate-availability-calendar-day.is-selected-start,
.realestate-availability-calendar-day.is-selected-end {
    background: linear-gradient(135deg, rgba(37, 99, 235, 0.95), rgba(14, 165, 233, 0.9));
    color: #ffffff;
    font-weight: 800;
    border-color: rgba(37, 99, 235, 0.9);
}

.realestate-availability-calendar-empty {
    margin: 0;
    color: rgba(71, 85, 105, 0.95);
    font-size: 0.88rem;
}

.realestate-modal-actions {
