}

.realestate-shortstay-host-stack {
    display: grid;
    gap: 0.45rem;
}

.realestate-shortstay-host-name {
    font-size: 1.05rem;
    font-weight: 800;
    color: #0f172a;
}

.realestate-shortstay-host-meta {
    font-size: 0.92rem;
    color: #475569;
}

.realestate-shortstay-host-badges {
    display: flex;
    flex-wrap: wrap;
