}

.short-term-offers-title {
    font-size: 0.74rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    font-weight: 800;
    color: #0f172a;
}

.short-term-offers-list {
    display: flex;
    flex-wrap: wrap;
    gap: 0.55rem;
