@media (max-width: 980px) {
    .realestate-shortstay-top-grid {
        grid-template-columns: 1fr;
    }
}

/* Service modal */
#service-modal .service-profile-modal {
    width: min(960px, 94vw);
    max-width: 960px;
    height: min(98vh, 980px);
    max-height: 98vh;
    padding: 0;
    overflow-x: hidden;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    background: #ffffff;
}

#service-modal .service-modal-media {
    position: relative;
    display: flex;
    flex-direction: column;
    background: #0b1b3a;
    min-height: 260px;
    max-height: 36vh;
}

#service-modal .service-modal-hero {
    position: relative;
    flex: 1;
    min-height: 0;
    isolation: isolate;
}

#service-modal .service-modal-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: var(--gallery-backdrop-image, none);
    background-size: cover;
    background-position: center;
    transform: scale(1.08);
    filter: blur(26px) saturate(1.08);
    opacity: 0.72;
    z-index: 0;
}

#service-modal .service-modal-hero img {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    object-fit: contain;
    object-position: center center;
    padding: 0.35rem;
    filter: drop-shadow(0 18px 38px rgba(2, 6, 23, 0.28));
    display: block;
}

#service-modal .service-modal-hero::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(15, 23, 42, 0.15) 0%, rgba(15, 23, 42, 0.65) 100%);
    z-index: 2;
}

#service-modal .service-modal-hero-overlay {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: 1rem;
    z-index: 3;
}

#service-modal .service-modal-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

#service-modal .service-modal-tag {
    padding: 0.3rem 0.65rem;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.7);
    border: 1px solid rgba(226, 232, 240, 0.2);
    color: rgba(248, 250, 252, 0.95);
    font-size: 0.7rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

#service-modal .service-modal-provider {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.6rem 0.75rem;
    border-radius: 16px;
    background: rgba(15, 23, 42, 0.72);
    border: 1px solid rgba(226, 232, 240, 0.2);
    color: rgba(248, 250, 252, 0.96);
    box-shadow: 0 16px 36px rgba(2, 6, 23, 0.45);
}

#service-modal .service-modal-provider img {
    width: 44px;
    height: 44px;
    border-radius: 14px;
    object-fit: cover;
    border: 1px solid rgba(226, 232, 240, 0.25);
}

#service-modal .service-modal-provider-name {
    font-weight: 800;
    font-size: 0.95rem;
}

#service-modal .service-modal-provider-role {
    font-size: 0.8rem;
    opacity: 0.85;
    margin-top: 0.15rem;
}

#service-modal .service-modal-provider-badge {
    margin-left: auto;
    padding: 0.25rem 0.6rem;
    border-radius: 999px;
    background: rgba(34, 197, 94, 0.2);
    border: 1px solid rgba(34, 197, 94, 0.35);
    color: rgba(187, 247, 208, 0.95);
    font-size: 0.7rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

#service-modal .service-modal-thumbs {
    display: flex;
    gap: 0.5rem;
    padding: 0.6rem 0.9rem 0.9rem;
    margin-top: -4.95rem;
    position: relative;
    z-index: 4;
    overflow-x: auto;
    background: linear-gradient(180deg, rgba(2, 6, 23, 0) 0%, rgba(2, 6, 23, 0.72) 38%, rgba(2, 6, 23, 0.88) 100%);
}

#service-modal .service-modal-thumbs::-webkit-scrollbar {
    display: none;
}

#service-modal .service-modal-thumb {
    flex: 0 0 auto;
    width: 72px;
    height: 54px;
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid rgba(226, 232, 240, 0.72);
    background: rgba(15, 23, 42, 0.45);
    cursor: pointer;
    padding: 0;
}

#service-modal .service-modal-thumb img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

#service-modal .service-modal-thumb.active {
    border-color: rgba(59, 130, 246, 0.8);
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.3);
}

#service-modal .service-modal-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 48px;
    height: 48px;
    border-radius: 999px;
    border: 1px solid rgba(226, 232, 240, 0.22);
    background: rgba(2, 6, 23, 0.55);
    color: rgba(248, 250, 252, 0.95);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 4;
    box-shadow: 0 14px 30px rgba(2, 6, 23, 0.22);
}

#service-modal .service-modal-prev { left: max(0.95rem, calc(env(safe-area-inset-left, 0px) + 0.4rem)); }
#service-modal .service-modal-next { right: max(0.95rem, calc(env(safe-area-inset-right, 0px) + 0.4rem)); }

#service-modal .service-modal-counter {
    position: absolute;
    right: max(1rem, calc(env(safe-area-inset-right, 0px) + 0.45rem));
    bottom: 5rem;
    z-index: 4;
    padding: 0.38rem 0.78rem;
    border-radius: 999px;
    background: rgba(2, 6, 23, 0.62);
    border: 1px solid rgba(226, 232, 240, 0.16);
    color: rgba(248, 250, 252, 0.92);
    font-weight: 800;
    font-size: 0.85rem;
    backdrop-filter: blur(5px);
    box-shadow: 0 14px 30px rgba(2, 6, 23, 0.2);
}

#service-modal .service-modal-nav:disabled {
    opacity: 0.4;
    cursor: default;
}

#service-modal .service-modal-nav:focus-visible {
    outline: 2px solid rgba(191, 219, 254, 0.85);
    outline-offset: 2px;
}

#service-modal .service-modal-body {
    padding: 1.1rem 1.2rem 1.25rem;
    background: rgba(255, 255, 255, 0.96);
    display: flex;
    flex-direction: column;
    gap: 1rem;
    overflow-y: auto;
    min-height: 0;
    flex: 1;
}

#service-modal .service-modal-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 1rem;
}

#service-modal .service-modal-subline {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem 1rem;
    color: rgba(71, 85, 105, 0.9);
    font-weight: 700;
    margin-top: 0.35rem;
}

#service-modal .service-modal-price-block {
    text-align: right;
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
}

#service-modal .service-modal-price-note {
    font-size: 0.85rem;
    color: rgba(71, 85, 105, 0.8);
    font-weight: 700;
}

#service-modal .service-modal-rating {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: 800;
    color: #0b1b3a;
}

#service-modal .service-rating-stars i {
    color: #fbbf24;
}

#service-modal .service-rating-stars .is-off {
    color: #e2e8f0;
}

#service-modal .service-rating-value {
