/* Mobile/Desktop parity for Home: preserve desktop sections without cramped controls. */
@media (max-width: 900px) {
    #home-content .home-topbar-left {
        flex: 1 1 auto;
        min-width: 0;
    }

    #home-content .home-topbar-right {
        flex: 0 1 auto;
        min-width: 0;
        max-width: 58%;
        overflow-x: auto;
        overflow-y: visible;
        -webkit-overflow-scrolling: touch;
        scrollbar-width: none;
        padding-bottom: 0.08rem;
    }

    #home-content .home-topbar-right::-webkit-scrollbar {
        height: 0;
        display: none;
    }

    #home-content .home-auth,
    #home-content .home-topbar-right > * {
        flex: 0 0 auto;
    }

    #home-content .home-logo-slogan {
        font-size: 0.96rem;
        line-height: 1.2;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    #home-content .home-search-row {
        width: 100%;
        min-width: 0;
        grid-template-columns: 1.5fr 1.5fr 1fr;
        align-items: end;
    }

    #home-content .home-search-actions {
        display: block;
        grid-column: 1 / -1;
        width: 100%;
    }

    #home-content #home-search-btn.btn-primary {
        width: 100%;
    }
}

@media (max-width: 640px) {
    #home-content .home-topbar {
        flex-direction: column;
        align-items: stretch;
        gap: 0.8rem;
    }

    #home-content .home-topbar-left {
        display: flex;
        width: 100%;
        min-width: 0;
        align-items: center;
        justify-content: flex-start;
        gap: 0.75rem;
        overflow: hidden;
    }

    #home-content .home-logo-slogan {
        display: block;
        flex: 1 1 auto;
        min-width: 0;
        font-size: clamp(1rem, 4.4vw, 1.22rem);
        line-height: 1.12;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    #home-content .home-topbar-right {
        max-width: 100%;
        width: 100%;
        justify-content: flex-start;
        gap: 0.6rem;
    }

    #home-content .home-auth {
        display: flex;
        gap: 0.6rem;
    }

    #home-content #notification-center-wrap {
        margin-left: auto;
    }

    #home-content .home-topbar-right {
        max-width: 100%;
    }

    #home-content .home-topbar-right .btn-primary.small {
        min-height: 34px;
        padding: 0 0.72rem;
        font-size: 0.92rem;
    }

    #home-content #home-login,
    #home-content #home-signup-btn {
        min-width: 88px;
    }

    #home-content #home-post-ad {
        min-width: 160px;
