.admin-dashboard-modal {
    width: min(96vw, 980px);
    max-width: 980px;
    max-height: 92vh;
    border-radius: 18px;
    padding: 1rem 1rem 1.1rem;
    overflow: auto;
    box-shadow: 0 28px 70px rgba(2, 6, 23, 0.28);
    background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
    border: 1px solid rgba(59, 130, 246, 0.16);
}

.admin-dashboard-head h3 {
    margin: 0;
    color: #0f172a;
    font-size: 1.15rem;
}

.admin-dashboard-head p {
    margin: 0.3rem 0 0.8rem;
    color: #475569;
    font-weight: 600;
}

.admin-dashboard-stats {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
    gap: 0.55rem;
    margin-bottom: 0.85rem;
}

.admin-stat {
    border: 1px solid rgba(148, 163, 184, 0.26);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.94);
    padding: 0.55rem 0.65rem;
    display: flex;
    flex-direction: column;
    gap: 0.22rem;
}

.admin-stat span {
    color: #64748b;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 800;
}

.admin-stat strong {
    color: #0f172a;
    font-size: 1rem;
    font-weight: 900;
}

.admin-dashboard-filters {
    display: flex;
    flex-wrap: wrap;
    gap: 0.55rem;
    align-items: center;
    margin-bottom: 0.85rem;
}

.admin-dashboard-filters select {
    min-width: 150px;
    border-radius: 10px;
    border: 1px solid rgba(148, 163, 184, 0.35);
    background: #ffffff;
    color: #0f172a;
    padding: 0.45rem 0.55rem;
    font-weight: 700;
}

.admin-moderation-list {
    display: grid;
    gap: 0.65rem;
    max-height: 50vh;
    overflow: auto;
    padding-right: 0.2rem;
}

.admin-application-queues,
.admin-application-list {
    display: grid;
    gap: 0.65rem;
}

.admin-application-section {
    display: grid;
    gap: 0.65rem;
    border: 1px solid rgba(59, 130, 246, 0.18);
    border-radius: 16px;
    background: rgba(239, 246, 255, 0.72);
    padding: 0.75rem;
}

.admin-application-section-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
}

.admin-application-section-head h4 {
    margin: 0;
    color: #0f172a;
    font-size: 0.95rem;
    font-weight: 900;
}

.admin-application-section-head p {
    margin: 0.2rem 0 0;
    color: #475569;
    font-size: 0.8rem;
    line-height: 1.4;
    font-weight: 600;
}

.admin-moderation-section {
    margin-top: 0.1rem;
    border-color: rgba(148, 163, 184, 0.28);
    background: rgba(248, 250, 252, 0.9);
}

.admin-report-card {
    border: 1px solid rgba(148, 163, 184, 0.25);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.95);
    padding: 0.75rem 0.8rem;
    box-shadow: 0 8px 20px rgba(15, 23, 42, 0.08);
}

.admin-report-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.6rem;
    margin-bottom: 0.3rem;
}

.admin-report-head strong {
    color: #0f172a;
    font-size: 0.8rem;
    letter-spacing: 0.06em;
}

.admin-report-status {
    display: inline-flex;
    align-items: center;
    border-radius: 999px;
    padding: 0.18rem 0.55rem;
    font-size: 0.68rem;
    font-weight: 900;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    border: 1px solid transparent;
}

.admin-report-status.status-open {
    color: #1e3a8a;
    background: rgba(59, 130, 246, 0.14);
    border-color: rgba(59, 130, 246, 0.3);
}

.admin-report-status.status-resolved {
    color: #166534;
    background: rgba(34, 197, 94, 0.14);
    border-color: rgba(34, 197, 94, 0.3);
}

.admin-report-status.status-dismissed {
    color: #9f1239;
    background: rgba(244, 63, 94, 0.12);
    border-color: rgba(244, 63, 94, 0.26);
}

.admin-report-target {
    margin: 0 0 0.22rem;
    color: #334155;
    font-weight: 700;
    font-size: 0.82rem;
}

.admin-report-reason {
    margin: 0;
    color: #0f172a;
    line-height: 1.4;
    font-size: 0.88rem;
}

.admin-report-foot {
    margin-top: 0.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.6rem;
    flex-wrap: wrap;
}

.admin-report-foot > span {
    color: #64748b;
    font-size: 0.75rem;
    font-weight: 700;
}

.admin-report-actions {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    flex-wrap: wrap;
}

.admin-empty {
    border: 1px dashed rgba(148, 163, 184, 0.45);
    border-radius: 14px;
    background: rgba(248, 250, 252, 0.92);
    color: #64748b;
    font-weight: 700;
    padding: 0.95rem 1rem;
}

@media (max-width: 720px) {
    .admin-dashboard-modal {
        width: calc(100vw - 1rem);
        max-height: calc(100vh - 1rem);
        border-radius: 16px;
        padding: 0.85rem;
    }
    .admin-dashboard-filters select {
        min-width: 0;
        width: 100%;
    }
    .admin-application-section-head {
        align-items: stretch;
        flex-direction: column;
    }
    .admin-application-section-head .admin-report-status {
        align-self: flex-start;
    }
}

/* Match Modal */
.match-content {
    background: linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%);
    color: white;
    padding: 3rem 2rem;
    text-align: center;
    border-radius: 20px;
    margin: 2rem;
    max-height: 90vh;
    position: relative;
    overflow-x: hidden;
    overflow-y: auto;
    scrollbar-gutter: stable;
}

.match-content .modal-close-btn {
    background: rgba(255, 255, 255, 0.18);
    color: #f8fafc;
}

.match-content .modal-close-btn:hover {
    background: rgba(255, 255, 255, 0.28);
}

.match-animation {
    font-size: 4rem;
    margin-bottom: 1rem;
    animation: heartbeat 1s ease-in-out infinite;
}

.match-content h2 {
    font-size: 2.5rem;
    margin-bottom: 2rem;
    font-weight: 700;
}

.match-photos {
    display: flex;
    justify-content: center;
    gap: 2rem;
    margin-bottom: 2rem;
}

.match-photos img {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 4px solid white;
}

.match-content p {
    font-size: 1.2rem;
    margin-bottom: 2rem;
    opacity: 0.9;
}

.match-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
}

.match-actions button {
    padding: 1rem 2rem;
    border-radius: 25px;
    border: none;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
}

/* SOS floating button */
.sos-btn {
    position: fixed;
    right: 16px;
    bottom: 96px; /* above bottom nav */
    width: 56px;
    height: 56px;
    border-radius: 50%;
    border: none;
    background: #ff6b6b;
    color: white;
    box-shadow: 0 8px 24px rgba(255, 107, 107, 0.5);
    z-index: 200;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
}

/* Responsive Design */
@media (max-width: 768px) {
    .card-stack {
        height: 50vh;
    }
    
    .match-photos {
