/* Animations */
@keyframes slideIn {
    from {
        transform: translateX(100%);
        opacity: 0;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

@keyframes slideOut {
    from {
        transform: translateX(0);
        opacity: 1;
    }
    to {
        transform: translateX(-100%);
        opacity: 0;
    }
}

.card.swipe-right {
    animation: slideOut 0.3s ease-out forwards;
    transform: rotate(20deg);
}

.card.swipe-left {
    animation: slideOut 0.3s ease-out forwards;
    transform: rotate(-20deg);
}

/* Status indicators */
.online-status {
    display: inline-block;
    width: 10px;
    height: 10px;
    background: #22c55e;
    border-radius: 50%;
    margin-left: 0.5rem;
}

.offline-status {
    display: inline-block;
    width: 10px;
    height: 10px;
    background: #999;
    border-radius: 50%;
    margin-left: 0.5rem;
}

/* Media Lightbox */
body.media-lightbox-open { overflow: hidden; }

.media-lightbox {
    position: fixed;
    inset: 0;
    width: 100vw;
    height: 100vh;
    height: 100dvh;
    background: #020617;
    display: block;
    padding: 0;
    z-index: 5000;
    overflow: hidden;
}
.media-lightbox.hidden { display: none; }
.media-lightbox-frame {
    width: 100vw;
    height: 100vh;
    height: 100dvh;
    max-width: none;
    max-height: none;
    border-radius: 0;
    overflow: hidden;
    background: #020617;
    box-shadow: none;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
}
.media-lightbox-frame img {
    display: block;
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    object-fit: contain;
    background: #020617;
    transition: transform 0.25s ease;
}
.media-lightbox-frame video {
    display: block;
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    object-fit: contain;
    background: #020617;
}

.media-lightbox-thumbs {
    position: absolute;
    right: clamp(4.5rem, 8vw, 7rem);
    bottom: max(0.75rem, env(safe-area-inset-bottom, 0px));
    left: clamp(4.5rem, 8vw, 7rem);
    z-index: 4;
    width: auto;
    max-width: none;
    display: flex;
    gap: 0.5rem;
    overflow-x: auto;
    overflow-y: hidden;
    padding: 0.55rem;
    border-radius: 16px;
    background: linear-gradient(180deg, rgba(2, 6, 23, 0.08), rgba(2, 6, 23, 0.78));
    scrollbar-width: none;
}
.media-lightbox-thumbs::-webkit-scrollbar { display: none; }
.ml-thumb {
    flex: 0 0 auto;
    width: 62px;
    height: 44px;
    border-radius: 12px;
    border: 1px solid rgba(226, 232, 240, 0.22);
    background: rgba(2, 6, 23, 0.5);
    overflow: hidden;
    cursor: pointer;
    padding: 0;
}
.ml-thumb img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    opacity: 0.95;
}
.ml-thumb.ml-thumb-video {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: rgba(248, 250, 252, 0.92);
    font-size: 1.05rem;
    background: radial-gradient(circle at 30% 20%, rgba(56, 189, 248, 0.22), transparent 55%),
                radial-gradient(circle at 70% 80%, rgba(124, 58, 237, 0.22), transparent 60%),
                rgba(2, 6, 23, 0.55);
}
.ml-thumb.active {
    border-color: rgba(56, 189, 248, 0.75);
    box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.24);
}
.media-lightbox-caption {
    position: absolute;
    bottom: 5.4rem;
    left: 50%;
    z-index: 4;
    transform: translateX(-50%);
    color: #f9fafb;
    font-size: 0.9rem;
    text-align: center;
    max-width: min(82vw, 640px);
    max-height: min(25vh, 12rem);
    margin: 0;
    padding: 0.6rem 0.8rem;
    overflow-y: auto;
    border-radius: 14px;
    background: rgba(2, 6, 23, 0.72);
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.65);
    backdrop-filter: blur(8px);
}

.profile-modal-phone {
    margin: 0.35rem 0 0;
    color: rgba(51, 65, 85, 0.9);
    font-weight: 700;
}
.profile-modal-phone a {
    color: #1d4ed8;
    font-weight: 900;
    text-decoration: none;
}
.profile-modal-phone a:hover { text-decoration: underline; }
.media-lightbox-counter {
    position: absolute;
    top: max(1rem, env(safe-area-inset-top, 0px));
    left: max(1rem, env(safe-area-inset-left, 0px));
    z-index: 4;
    color: #e2e8f0;
    font-size: 0.8rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 0.45rem 0.68rem;
    border-radius: 999px;
    background: rgba(2, 6, 23, 0.72);
    opacity: 1;
    backdrop-filter: blur(8px);
}
.media-lightbox-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 52px;
    height: 52px;
    border-radius: 999px;
    border: none;
    background: rgba(15, 23, 42, 0.65);
    color: #f9fafb;
    font-size: 1.25rem;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background 0.2s ease, transform 0.2s ease;
    z-index: 1;
    backdrop-filter: blur(4px);
    box-shadow: 0 18px 36px rgba(15, 23, 42, 0.45);
}
.media-lightbox-nav:hover { background: rgba(15, 23, 42, 0.9); }
.media-lightbox-nav:active { transform: translateY(-50%) scale(0.96); }
.media-lightbox-nav:disabled { opacity: 0.4; cursor: default; }
.media-lightbox-nav:focus-visible {
    outline: 2px solid #38bdf8;
    outline-offset: 3px;
}
.media-lightbox-prev { left: clamp(1rem, 4vw, 3rem); }
.media-lightbox-next { right: clamp(1rem, 4vw, 3rem); }
.media-lightbox-close {
    position: absolute;
    top: max(1rem, env(safe-area-inset-top, 0px));
    right: max(1rem, env(safe-area-inset-right, 0px));
    width: 44px;
    height: 44px;
    border-radius: 999px;
    border: none;
    background: rgba(15, 23, 42, 0.65);
    color: #f9fafb;
    font-size: 1.1rem;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background 0.2s ease;
    backdrop-filter: blur(4px);
    box-shadow: 0 16px 32px rgba(15, 23, 42, 0.45);
    z-index: 2;
}
.media-lightbox-close:hover { background: rgba(15, 23, 42, 0.85); }

@media (max-width: 900px) {
    .media-lightbox { padding: 0; }
}

@media (max-width: 640px) {
    .media-lightbox {
        padding: 0;
    }
    .media-lightbox-frame {
        width: 100%;
        height: 100%;
    }
    .media-lightbox-frame > img.media-lightbox-image {
        width: 100vw !important;
        height: auto !important;
        min-width: 100vw !important;
        max-width: 100vw !important;
        max-height: 100dvh !important;
        object-fit: contain !important;
    }
    .media-lightbox-close {
        top: calc(0.75rem + env(safe-area-inset-top, 0px));
        right: calc(0.75rem + env(safe-area-inset-right, 0px));
        width: 44px;
        height: 44px;
        background: rgba(2, 6, 23, 0.78);
        z-index: 6;
    }
    .media-lightbox-nav {
        width: 44px;
        height: 44px;
        font-size: 1.05rem;
        background: rgba(2, 6, 23, 0.68);
        z-index: 5;
    }
    .media-lightbox-prev { left: max(0.65rem, env(safe-area-inset-left, 0px)); }
    .media-lightbox-next { right: max(0.65rem, env(safe-area-inset-right, 0px)); }
    .media-lightbox-thumbs {
        right: 0;
        bottom: 0;
        left: 0;
        width: 100%;
        padding: 0.65rem max(0.75rem, env(safe-area-inset-right, 0px)) calc(0.65rem + env(safe-area-inset-bottom, 0px)) max(0.75rem, env(safe-area-inset-left, 0px));
        border-radius: 0;
        background: linear-gradient(180deg, rgba(2, 6, 23, 0), rgba(2, 6, 23, 0.9));
    }
    .media-lightbox-counter {
        top: calc(0.9rem + env(safe-area-inset-top, 0px));
        left: max(0.75rem, env(safe-area-inset-left, 0px));
    }
    .media-lightbox-caption,
    .media-lightbox-actions {
        display: none;
    }
}
